class Solution {
  public long maximumCoins(int[][] coins, int k) {
    int n = coins.length;
    long[][] seg = new long[n][];
    for (int i = 0; i < n; i++) seg[i] = new long[] {coins[i][0], coins[i][1], coins[i][2]};
    java.util.Arrays.sort(seg, (a, b) -> Long.compare(a[0], b[0]));
    long ans = scan(seg, k);
    long[][] mirror = new long[n][];
    for (int i = 0; i < n; i++) {
      long[] s = seg[n - 1 - i];
      mirror[i] = new long[] {-s[1], -s[0], s[2]};
    }
    return Math.max(ans, scan(mirror, k));
  }

  // best window starting at the left end of some segment
  private static long scan(long[][] seg, int k) {
    int n = seg.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + (seg[i][1] - seg[i][0] + 1) * seg[i][2];
    long best = 0;
    int j = 0;
    for (int i = 0; i < n; i++) {
      long end = seg[i][0] + k - 1;
      if (j < i) j = i;
      while (j < n && seg[j][1] <= end) j++;
      long total = pre[j] - pre[i];
      if (j < n && seg[j][0] <= end) total += (end - seg[j][0] + 1) * seg[j][2];
      best = Math.max(best, total);
    }
    return best;
  }
}
